package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen1Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        // We need to spy on the factory because many methods called are protected
        factory = spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        type = mock(JavaType.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);
    }

    /**
     * Test Case 1: Custom deserializer is found via _findCustomBeanDeserializer.
     */
    @Test
    public void testCreateBeanDeserializer_CustomFound() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = mock(JsonDeserializer.class);
        doReturn(customDeser).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(factory)._findCustomBeanDeserializer(type, config, beanDesc);
    }

    /**
     * Test Case 2: Type is a Throwable, should trigger buildThrowableDeserializer.
     */
    @Test
    public void testCreateBeanDeserializer_IsThrowable() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(true);

        JsonDeserializer<Object> throwableDeser = mock(JsonDeserializer.class);
        doReturn(throwableDeser).when(factory).buildThrowableDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(throwableDeser, result);
        verify(factory).buildThrowableDeserializer(ctxt, type, beanDesc);
    }

    /**
     * Test Case 3: Type is abstract and not primitive, materialization succeeds.
     */
    @Test
    public void testCreateBeanDeserializer_AbstractTypeMaterialized() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);

        JavaType concreteType = mock(JavaType.class);
        doReturn(concreteType).when(factory).materializeAbstractType(any(), any(), any());
        doReturn(beanDesc).when(config).introspect(concreteType);

        JsonDeserializer<Object> beanDeser = mock(JsonDeserializer.class);
        doReturn(beanDeser).when(factory).buildBeanDeserializer(any(), eq(concreteType), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeser, result);
        verify(factory).materializeAbstractType(ctxt, type, beanDesc);
        verify(config).introspect(concreteType);
    }

    /**
     * Test Case 4: Type is abstract, but materialization fails (returns null).
     */
    @Test
    public void testCreateBeanDeserializer_AbstractTypeMaterializationFails() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);
        doReturn(null).when(factory).materializeAbstractType(any(), any(), any());

        // Fallthrough to findStdDeserializer
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        // Mock as non-bean to return null
        doReturn(false).when(factory).isPotentialBeanType(any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    /**
     * Test Case 5: Standard deserializer is found via findStdDeserializer.
     */
    @Test
    public void testCreateBeanDeserializer_StdDeserializerFound() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        // Ensure we don't enter abstract block
        when(type.isAbstract()).thenReturn(false);

        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);
        doReturn(stdDeser).when(factory).findStdDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    /**
     * Test Case 6: Not a standard deserializer, not a potential bean type -> returns null.
     */
    @Test
    public void testCreateBeanDeserializer_NotPotentialBean() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        when(type.getRawClass()).thenReturn(String.class);
        doReturn(false).when(factory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    /**
     * Test Case 7: Is a potential bean type -> builds bean deserializer.
     */
    @Test
    public void testCreateBeanDeserializer_BuildsBeanDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        Class<?> beanClass = TestBean.class;
        when(type.getRawClass()).thenReturn(beanClass);
        doReturn(true).when(factory).isPotentialBeanType(beanClass);

        JsonDeserializer<Object> beanDeser = mock(JsonDeserializer.class);
        doReturn(beanDeser).when(factory).buildBeanDeserializer(eq(ctxt), eq(type), eq(beanDesc));

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeser, result);
    }

    /**
     * Test Case 8: Abstract type but it is a primitive (edge case in logic).
     */
    @Test
    public void testCreateBeanDeserializer_AbstractButPrimitive() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(true); // Should skip materialization

        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        when(type.getRawClass()).thenReturn(int.class);
        doReturn(false).when(factory).isPotentialBeanType(int.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);
        assertNull(result);
    }

    public static class TestBean {
        public String name;
    }
}
